def parse_url(url: str) -> dict:
    protocol = url.split('://')[0]
    rest = url.split('://')[1]

    # Fragment ayır
    fragment = None
    if '#' in rest:
        rest, fragment = rest.split('#', 1)

    # Query ayır
    query = {}
    if '?' in rest:
        rest, query_str = rest.split('?', 1)
        for param in query_str.split('&'):
            if '=' in param:
                key, value = param.split('=', 1)
                query[key] = value

    # Host/port ve path ayır
    if '/' in rest:
        host_part, path = rest.split('/', 1)
        path = '/' + path
    else:
        host_part = rest
        path = '/'

    # Port ayır
    port = None
    if ':' in host_part:
        host, port_str = host_part.split(':', 1)
        port = int(port_str)
    else:
        host = host_part

    return {
        'protocol': protocol,
        'host': host,
        'port': port,
        'path': path,
        'query': query,
        'fragment': fragment
    }

