function parseUrl(url) {
  const protocolEnd = url.indexOf('://');
  const protocol = url.slice(0, protocolEnd);
  let rest = url.slice(protocolEnd + 3);

  let fragment = null;
  const hashIdx = rest.indexOf('#');
  if (hashIdx !== -1) {
    fragment = rest.slice(hashIdx + 1);
    rest = rest.slice(0, hashIdx);
  }

  let query = {};
  const qIdx = rest.indexOf('?');
  if (qIdx !== -1) {
    const queryStr = rest.slice(qIdx + 1);
    rest = rest.slice(0, qIdx);
    queryStr.split('&').forEach(param => {
      const eqIdx = param.indexOf('=');
      if (eqIdx !== -1) {
        query[param.slice(0, eqIdx)] = param.slice(eqIdx + 1);
      }
    });
  }

  let path = '/';
  const slashIdx = rest.indexOf('/');
  let hostPart = rest;
  if (slashIdx !== -1) {
    hostPart = rest.slice(0, slashIdx);
    path = rest.slice(slashIdx);
  }

  let port = null;
  let host = hostPart;
  const colonIdx = hostPart.indexOf(':');
  if (colonIdx !== -1) {
    host = hostPart.slice(0, colonIdx);
    port = parseInt(hostPart.slice(colonIdx + 1), 10);
  }

  return { protocol, host, port, path, query, fragment };
}
